record Page<T>(List<T> content, int page, int size, long totalElements, int totalPages) {}

Page<Product> findPage(int page, int size) {
    long totalElements = count();
    int offset = (page - 1) * size;
    List<Product> content = new ArrayList<>();
    // "SELECT id, name FROM products ORDER BY id LIMIT ? OFFSET ?"
    int totalPages = (int) Math.ceil(totalElements / (double) size);
    return new Page<>(content, page, size, totalElements, totalPages);
}

