class CachedPageProvider {
  private Long cachedCount;
  Page<Product> findPageCached(int page, int size) {
    if (cachedCount == null) cachedCount = dao.count();
    List<Product> content = dao.findRawPage(page, size); // bez COUNT
    return new Page<>(content, page, size, cachedCount, ...);
  }
}

